To create a Discord bot with a ban command using Discord.js v14, follow these steps:

1. Create a new Discord application and add a bot to it. Make sure to enable the "Bot" and "Application Commands" (formerly known as "Slash Commands") options in the Discord Developer Portal.

2. Install the necessary dependencies by running the following command in your terminal:

```
npm install discord.js @discordjs/builders
```

3. Create a new file named `index.js` and add the following code:

```javascript
const { Client, GatewayIntentBits } = require('discord.js');
const { Collection } = require('discord.js');
const { TOKEN, CLIENT_ID } = require('./config.json');

// Create a new Discord client
const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

// Load command handler
const commands = new Collection();
const commandFiles = fs.readdirSync('./commands').filter(file => file.endsWith('.js'));

for (const file of commandFiles) {
  const command = require(`./commands/${file}`);
  commands.set(command.data.name, command);
}

// Register global application command for "ban" command
client.on('ready', async () => {
  try {
    await client.application.commands.set([
      {
        name: 'ban',
        description: 'Bans a user from the server',
        options: [
          {
            name: 'user',
            description: 'The user to ban',
            type: Discord.ApplicationCommandOptionType.User,
            required: true,
          },
          {
            name: 'days',
            description: 'The number of days to ban the user for',
            type: Discord.ApplicationCommandOptionType.Integer,
            required: false,
          },
          {
            name: 'reason',
            description: 'The reason for the ban',
            type: Discord.ApplicationCommandOptionType.String,
            required: false,
          },
        ],
      },
    ]);
  } catch (error) {
    console.error(error);
  }
});

// Handle command interaction
client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  const command = commands.get(interaction.commandName);

  if (!command) return;

  try {
    await command.execute(interaction);
  } catch (error) {
    console.error(error);
    await interaction.reply({ content: 'There was an error while executing this command!', ephemeral: true });
  }
});

// Login to Discord with your bot token
client.login(TOKEN);
```

4. In the same directory, create a new folder named `commands` and add a new file inside it named `ban.js`. Add the following code to this file:

```javascript
const { ApplicationCommandOptionType, EmbedBuilder } = require('discord.js');
const { BAN_EMOJI, ERROR_EMOJI } = require('./config.json');

module.exports = {
  data: {
    name: 'ban',
    description: 'Bans a user from the server',
    options: [
      {
        name: 'user',
        description: 'The user to ban',
        type: ApplicationCommandOptionType.User,
        required: true,
      },
      {
        name: 'days',
        description: 'The number of days to ban the user for',
        type: ApplicationCommandOptionType.Integer,
        required: false,
      },
      {
        name: 'reason',
        description: 'The reason for the ban',
        type: ApplicationCommandOptionType.String,
        required: false,
      },
    ],
  },

  async execute(interaction) {
    const user = interaction.options.getUser('user');
    const days = interaction.options.getInteger('days') || 0;
    const reason = interaction.options.getString('reason') || 'No reason provided';

    // Ban the user
    await interaction.guild.members.ban(user, { days: days });

    // Send a confirmation message
    const embed = new EmbedBuilder()
      .setTitle(`${BAN_EMOJI} User banned!`)
      .setDescription(`**User:** ${user.tag}\n**Days:** ${days}\n**Reason:** ${reason}`)
      .setColor('#ff0000');

    await interaction.reply({ embeds: [embed] });
  },
};
```

5. In the same directory, create a new file named `config.json` and add the following content:

```json
