std::string markdown_to_html(const std::string& markdown) {
    // Initialize Pandoc options
    std::string pandoc_options = "--from=markdown --to=html5 --output=-";

    // Convert Markdown to HTML
    std::string html;
    auto pandoc_result = pandoc::Pandoc::run(pandoc_options, markdown, [&](pandoc::Pandoc::io::IOSink& sink) {
        sink << html;
    });

    if (pandoc_result != pandoc::Pandoc::Status::OK) {
        std::cerr << "Error converting Markdown to HTML" << std::endl;
        return "";
    }

    return html;
}
